import csv
import json
import os
from pathlib import Path

filenames = ["20190119_pipeline.csv", "20190120_pipeline.csv", "20190121_pipeline.csv"]
segments = [{"临潼站", "高陵站"}, {"华阴站", "潼关站"}]
lines = {"西气东输二线", "西气东输三线"}
base = Path(os.environ["PIPELINE_FLOW_DIR"])

rows = []
for filename in filenames:
    path = base / filename
    data = None
    used_encoding = None
    for encoding in ("utf-8-sig", "gb18030"):
        try:
            with path.open("r", encoding=encoding, newline="") as f:
                data = list(csv.DictReader(f))
            used_encoding = encoding
            break
        except UnicodeDecodeError:
            continue
    if data is None:
        raise RuntimeError(f"Could not decode {filename}")
    for row in data:
        endpoints = {row.get("起点站名", "").strip(), row.get("终点站名", "").strip()}
        line = row.get("管道划分", "").strip()
        if endpoints in segments and line in lines:
            raw_flow = row.get("管道流量", "").strip()
            rows.append({
                "source_file": filename,
                "起点站名": row.get("起点站名", "").strip(),
                "终点站名": row.get("终点站名", "").strip(),
                "管道划分": line,
                "管道流量": float(raw_flow),
                "绝对流量": abs(float(raw_flow)),
                "encoding": used_encoding,
            })

sums = {line: sum(r["绝对流量"] for r in rows if r["管道划分"] == line) for line in sorted(lines)}
counts = {line: sum(1 for r in rows if r["管道划分"] == line) for line in sorted(lines)}
result = {
    "matched_rows": rows,
    "row_counts": counts,
    "absolute_flow_sums": sums,
    "difference_second_minus_third": sums["西气东输二线"] - sums["西气东输三线"],
}
print(json.dumps(result, ensure_ascii=False, indent=2))

import csv
import json
import os
from datetime import date, timedelta
from pathlib import Path

flow_dir = Path(os.environ["PIPELINE_FLOW_DIR"])
start_day = date(2019, 1, 24)
end_day = date(2019, 1, 30)
segments = {("中卫站", "古浪站"), ("古浪站", "永昌站")}
lines = ["西气东输一线", "西气东输二线", "西气东输三线"]

totals = {line: 0.0 for line in lines}
by_day = {}
row_counts = {line: 0 for line in lines}
current = start_day
while current <= end_day:
    filename = current.strftime("%Y%m%d_pipeline.csv")
    path = flow_dir / filename
    daily = {line: 0.0 for line in lines}
    daily_counts = {line: 0 for line in lines}
    with path.open("r", encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            key = (row["起点站名"], row["终点站名"])
            line = row["管道划分"]
            if key in segments and line in totals:
                value = abs(float(row["管道流量"]))
                totals[line] += value
                daily[line] += value
                row_counts[line] += 1
                daily_counts[line] += 1
    by_day[current.isoformat()] = {"absolute_flow_sum": daily, "matched_rows": daily_counts}
    current += timedelta(days=1)

ranking = sorted(totals.items(), key=lambda item: item[1], reverse=True)
differences = {}
for i, (higher_line, higher_value) in enumerate(ranking):
    for lower_line, lower_value in ranking[i + 1:]:
        differences[f"{higher_line}-{lower_line}"] = higher_value - lower_value

print(json.dumps({
    "window": [start_day.isoformat(), end_day.isoformat()],
    "segments": [list(x) for x in sorted(segments)],
    "totals": totals,
    "matched_rows": row_counts,
    "ranking": ranking,
    "differences": differences,
    "daily_checks": by_day
}, ensure_ascii=False, indent=2))

